--[[\n    PROJECT RADIANT | MAIN ENTRY POINT\n    Version: 0.43\n    Modular Architecture with Enhanced UI\n]]\n\n-- ============================================================\n-- LIBRARY LOADING\n-- ============================================================\nlocal repo = \"https://raw.githubusercontent.com/xXnikotosYTXx/LinoriaLibRewrite/main/\"\nlocal Library = loadstring(game:HttpGet(repo .. \"Library.lua\"))()\nlocal ThemeManager = loadstring(game:HttpGet(repo .. \"addons/ThemeManager.lua\"))()\nlocal SaveManager = loadstring(game:HttpGet(repo .. \"addons/SaveManager.lua\"))()\n\n-- ============================================================\n-- GLOBAL SERVICES\n-- ============================================================\nlocal TweenService = game:GetService(\"TweenService\")\nlocal camera = workspace.CurrentCamera\nlocal Players = game:GetService(\"Players\")\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ============================================================\n-- CLEANUP PREVIOUS INSTANCES\n-- ============================================================\nif getgenv().current_esplib and getgenv().current_esplib.force_cleanup then\n    getgenv().current_esplib.force_cleanup()\nend\n\n-- ============================================================\n-- EXTERNAL LIBRARIES LOADING\n-- ============================================================\nlocal esplib = loadstring(game:HttpGet(\"https://raw.githubusercontent.com/xXnikotosYTXx/esp-lib.lua/refs/heads/main/source.lua\"))()\ngetgenv().current_esplib = esplib\n\nlocal aimbot_url = \"https://raw.githubusercontent.com/xXnikotosYTXx/esp-lib.lua/refs/heads/main/aimsource.lua\"\nlocal AimbotEnvironment = loadstring(game:HttpGet(aimbot_url))()\nAimbotEnvironment:Load()\n\n-- Disable built-in aimbot keybinds\nAimbotEnvironment.Settings.TriggerKey = nil\nAimbotEnvironment.TriggerActive = true\n\n-- ============================================================\n-- WINDOW CREATION\n-- ============================================================\nlocal Window = Library:CreateWindow({\n    Title = \"Project | Radiant | 0.43\",\n    Center = true,\n    AutoShow = true,\n    Resizable = true,\n    ShowCustomCursor = true,\n    UnlockMouseWhileOpen = true,\n    NotifySide = \"Left\",\n    TabPadding = 8,\n    MenuFadeTime = 0.2\n})\n\n-- ============================================================\n-- TAB CREATION\n-- ============================================================\nlocal Tabs = {\n    Combat   = Window:AddTab(\"⚔️ Combat\"),\n    ESP      = Window:AddTab(\"👁️ ESP\"),\n    Visuals  = Window:AddTab(\"✨ Visuals\"),\n    Players  = Window:AddTab(\"👥 Players\"),\n    Utility  = Window:AddTab(\"🔧 Utility\"),\n    Settings = Window:AddTab(\"⚙️ Settings\"),\n}\n\n-- ============================================================\n-- GLOBAL STATE\n-- ============================================================\nlocal State = {\n    autoESP = false,\n    autoDummy = false,\n    Connections = {}\n}\n\n-- ============================================================\n-- UI INITIALIZATION - COMBAT TAB\n-- ============================================================\nlocal function InitCombatUI()\n    local AimSettings = AimbotEnvironment.Settings\n    local AimFOV = AimbotEnvironment.FOVSettings\n    \n    -- ============ TARGET LOCK SETTINGS ============\n    local TargetBox = Tabs.Combat:AddLeftGroupbox(\"🎯 Target Lock Settings\")\n    TargetBox:AddToggle(\"AimEnabled\", {\n        Text = \"Enable Aimbot\",\n        Default = AimSettings.Enabled,\n        Tooltip = \"Activates the main aimbot system\",\n        Callback = function(v) AimSettings.Enabled = v end\n    }):AddKeyPicker(\"AimEnabledKey\", {\n        Default = \"None\",\n        SyncToggleState = true,\n        Mode = \"Toggle\",\n        Text = \"Aimbot Toggle Key\"\n    })\n    \n    TargetBox:AddDropdown(\"AimLockPart\", {\n        Text = \"Target Bone\",\n        Values = {\"Head\", \"HumanoidRootPart\", \"Torso\", \"Left Arm\", \"Right Arm\", \"Left Leg\", \"Right Leg\"},\n        Default = AimSettings.LockPart,\n        Callback = function(v) AimSettings.LockPart = v end\n    })\n    \n    TargetBox:AddDropdown(\"AimLockMode\", {\n        Text = \"Lock Method\",\n        Values = {\"CFrame\", \"Mouse\"},\n        Default = AimSettings.LockMode == 1 and \"CFrame\" or \"Mouse\",\n        Callback = function(v) AimSettings.LockMode = (v == \"CFrame\" and 1 or 2) end\n    })\n    \n    TargetBox:AddDivider()\n    TargetBox:AddLabel(\"Detection Filters:\")\n    TargetBox:AddToggle(\"AimTeamCheck\", {Text = \"🛡️ Team Check\", Default = AimSettings.TeamCheck, Callback = function(v) AimSettings.TeamCheck = v end})\n    TargetBox:AddToggle(\"AimWallCheck\", {Text = \"🧱 Wall Check\", Default = AimSettings.WallCheck, Callback = function(v) AimSettings.WallCheck = v end})\n    TargetBox:AddToggle(\"AimAliveCheck\", {Text = \"❤️ Alive Check\", Default = AimSettings.AliveCheck, Callback = function(v) AimSettings.AliveCheck = v end})\n    \n    -- ============ AIMING MODES ============\n    local TriggerBox = Tabs.Combat:AddLeftGroupbox(\"🔫 Aiming Modes\")\n    TriggerBox:AddToggle(\"AimSilent\", {\n        Text = \"🤫 Silent Aim\",\n        Default = AimSettings.SilentAim,\n        Tooltip = \"Silently bends bullets to target\",\n        Callback = function(v) AimSettings.SilentAim = v end\n    }):AddKeyPicker(\"AimSilentKey\", {\n        Default = \"None\",\n        SyncToggleState = true,\n        Mode = \"Toggle\",\n        Text = \"Silent Aim Key\"\n    })\n    \n    TriggerBox:AddToggle(\"AimCamera\", {\n        Text = \"📷 Camera Follow\",\n        Default = AimSettings.CameraAim,\n        Tooltip = \"Moves your view/mouse to target\",\n        Callback = function(v) AimSettings.CameraAim = v end\n    }):AddKeyPicker(\"AimCameraKey\", {\n        Default = \"RightClick\",\n        SyncToggleState = true,\n        Mode = \"Hold\",\n        Text = \"Camera Follow Key\"\n    })\n    \n    -- ============ SMOOTHING & PREDICTION ============\n    local PerfBox = Tabs.Combat:AddRightGroupbox(\"⚡ Smoothing & Prediction\")\n    PerfBox:AddLabel(\"Aim Smoothing:\")\n    PerfBox:AddSlider(\"AimSmoothing\", {\n        Text = \"📊 Smoothing Value\",\n        Default = AimSettings.Sensitivity,\n        Min = 0, Max = 1, Rounding = 2, Compact = true,\n        Callback = function(v) AimSettings.Sensitivity = v end\n    })\n    \n    PerfBox:AddSlider(\"AimMouseSens\", {\n        Text = \"🖱️ Mouse Sensitivity\",\n        Default = AimSettings.Sensitivity2,\n        Min = 1, Max = 10, Rounding = 1, Compact = true,\n        Callback = function(v) AimSettings.Sensitivity2 = v end\n    })\n    \n    PerfBox:AddDivider()\n    PerfBox:AddLabel(\"Prediction:\")\n    PerfBox:AddToggle(\"AimPrediction\", {\n        Text = \"🔮 Enable Prediction\",\n        Default = AimSettings.Prediction,\n        Callback = function(v) AimSettings.Prediction = v end\n    })\n    \n    PerfBox:AddSlider(\"AimPredAmount\", {\n        Text = \"🎯 Prediction Strength\",\n        Default = AimSettings.PredictionAmount,\n        Min = 0.05, Max = 0.5, Rounding = 3, Compact = true,\n        Callback = function(v) AimSettings.PredictionAmount = v end\n    })\n    \n    -- ============ FOV CIRCLE SETTINGS ============\n    local FOVBox = Tabs.Combat:AddRightGroupbox(\"🎪 FOV Circle Configuration\")\n    FOVBox:AddLabel(\"Main Settings:\")\n    FOVBox:AddToggle(\"AimFovEnabled\", {Text = \"✅ Enable FOV Circle\", Default = AimFOV.Enabled, Callback = function(v) AimFOV.Enabled = v end})\n    FOVBox:AddToggle(\"AimFovVisible\", {Text = \"👁️ Show Circle\", Default = AimFOV.Visible, Callback = function(v) AimFOV.Visible = v end})\n    FOVBox:AddToggle(\"AimFovDynamic\", {Text = \"🌊 Dynamic Spread\", Default = AimFOV.Dynamic, Callback = function(v) AimFOV.Dynamic = v end})\n    FOVBox:AddToggle(\"AimFovFilled\", {Text = \"🎨 Fill Circle\", Default = AimFOV.Filled, Callback = function(v) AimFOV.Filled = v end})\n    \n    FOVBox:AddDivider()\n    FOVBox:AddLabel(\"Radius Sizes:\")\n    FOVBox:AddSlider(\"AimFovBaseR\", {Text = \"🚶 Standing Radius\", Default = AimFOV.BaseRadius, Min = 10, Max = 800, Rounding = 0, Compact = true, Callback = function(v) AimFOV.BaseRadius = v end})\n    FOVBox:AddSlider(\"AimFovRunR\", {Text = \"🏃 Running Radius\", Default = AimFOV.RunRadius, Min = 10, Max = 800, Rounding = 0, Compact = true, Callback = function(v) AimFOV.RunRadius = v end})\n    FOVBox:AddSlider(\"AimFovJumpR\", {Text = \"⬆️ Jump Radius\", Default = AimFOV.JumpRadius, Min = 10, Max = 800, Rounding = 0, Compact = true, Callback = function(v) AimFOV.JumpRadius = v end})\n    \n    FOVBox:AddDivider()\n    FOVBox:AddLabel(\"Visual Properties:\")\n    FOVBox:AddSlider(\"AimFovSides\", {Text = \"⚙️ Segments\", Default = AimFOV.NumSides, Min = 3, Max = 100, Rounding = 0, Compact = true, Callback = function(v) AimFOV.NumSides = v end})\n    FOVBox:AddSlider(\"AimFovThickness\", {Text = \"━━ Line Thickness\", Default = AimFOV.Thickness, Min = 1, Max = 10, Rounding = 1, Compact = true, Callback = function(v) AimFOV.Thickness = v end})\n    FOVBox:AddSlider(\"AimFovTrans\", {Text = \"💧 Transparency\", Default = AimFOV.Transparency, Min = 0.1, Max = 1.0, Rounding = 2, Compact = true, Callback = function(v) AimFOV.Transparency = v end})\n    \n    -- ============ FOV COLORS ============\n    local ColorBox = Tabs.Combat:AddRightGroupbox(\"🎨 FOV Colors\")\n    ColorBox:AddLabel(\"🟢 Primary Color (Normal):\")\n    ColorBox:AddColorPicker(\"AimFovColor\", {Default = AimFOV.Color, Callback = function(v) AimFOV.Color = v end})\n    \n    ColorBox:AddDivider()\n    ColorBox:AddLabel(\"🔴 Target Locked Color:\")\n    ColorBox:AddColorPicker(\"AimFovLockedColor\", {Default = AimFOV.LockedColor, Callback = function(v) AimFOV.LockedColor = v end})\n    \n    ColorBox:AddDivider()\n    ColorBox:AddToggle(\"AimFovRainbow\", {Text = \"🌈 Rainbow Mode\", Default = AimFOV.RainbowColor, Callback = function(v) AimFOV.RainbowColor = v end})\nend\n\n-- ============================================================\n-- UI INITIALIZATION - ESP TAB\n-- ============================================================\nlocal function InitESPUI()\n    -- ============ BOX VISUALS ============\n    local BoxGroup = Tabs.ESP:AddLeftGroupbox(\"📦 Box Visuals\")\n    BoxGroup:AddLabel(\"Box Settings:\")\n    BoxGroup:AddToggle(\"BoxEnabled\", {Text = \"✅ Show Box\", Default = true, Callback = function(v) esplib.box.enabled = v end})\n    BoxGroup:AddDropdown(\"BoxType\", {Text = \"Style\", Values = {\"normal\", \"corner\"}, Default = 1, Callback = function(v) esplib.box.type = v end})\n    BoxGroup:AddSlider(\"BoxPadding\", {Text = \"Padding\", Default = 1.15, Min = 0.5, Max = 2.0, Rounding = 2, Compact = true, Callback = function(v) esplib.box.padding = v end})\n    \n    BoxGroup:AddDivider()\n    BoxGroup:AddLabel(\"🟫 Box Fill Color:\")\n    BoxGroup:AddColorPicker(\"BoxFillColor\", {Default = Color3.new(1,1,1), Callback = function(v) esplib.box.fill = v end})\n    \n    BoxGroup:AddLabel(\"⬛ Box Outline Color:\")\n    BoxGroup:AddColorPicker(\"BoxOutlineColor\", {Default = Color3.new(0,0,0), Callback = function(v) esplib.box.outline = v end})\n    \n    -- ============ TEXT DISPLAY ============\n    local TextGroup = Tabs.ESP:AddLeftGroupbox(\"📝 Text & Information\")\n    TextGroup:AddLabel(\"Player Names:\")\n    TextGroup:AddToggle(\"NameEnabled\", {Text = \"✅ Show Names\", Default = true, Callback = function(v) esplib.name.enabled = v end})\n    TextGroup:AddToggle(\"ShowHealth\", {Text = \"❤️ Include Health\", Default = true, Callback = function(v) esplib.name.show_health = v end})\n    TextGroup:AddSlider(\"NameSize\", {Text = \"Size\", Default = 13, Min = 8, Max = 24, Rounding = 0, Compact = true, Callback = function(v) esplib.name.size = v end})\n    \n    TextGroup:AddLabel(\"⚪ Name Color:\")\n    TextGroup:AddColorPicker(\"NameColor\", {Default = Color3.new(1,1,1), Callback = function(v) esplib.name.fill = v end})\n    \n    TextGroup:AddDivider()\n    TextGroup:AddLabel(\"Distance Display:\")\n    TextGroup:AddToggle(\"DistanceEnabled\", {Text = \"✅ Show Distance\", Default = true, Callback = function(v) esplib.distance.enabled = v end})\n    TextGroup:AddSlider(\"DistanceSize\", {Text = \"Size\", Default = 13, Min = 8, Max = 24, Rounding = 0, Compact = true, Callback = function(v) esplib.distance.size = v end})\n    \n    TextGroup:AddLabel(\"📏 Distance Color:\")\n    TextGroup:AddColorPicker(\"DistanceColor\", {Default = Color3.new(1,1,1), Callback = function(v) esplib.distance.fill = v end})\n    \n    -- ============ HEALTH VISUALIZATION ============\n    local HealthGroup = Tabs.ESP:AddRightGroupbox(\"❤️ Health Visualization\")\n    HealthGroup:AddLabel(\"Healthbar Settings:\")\n    HealthGroup:AddToggle(\"HealthEnabled\", {Text = \"✅ Show Healthbar\", Default = true, Callback = function(v) esplib.healthbar.enabled = v end})\n    HealthGroup:AddDropdown(\"HealthPosition\", {Text = \"Position\", Values = {\"left\", \"right\", \"bottom\"}, Default = 1, Callback = function(v) esplib.healthbar.position = v end})\n    HealthGroup:AddToggle(\"HealthGradient\", {Text = \"🌈 Gradient Effect\", Default = true, Callback = function(v) esplib.healthbar.gradient = v end})\n    \n    HealthGroup:AddDivider()\n    HealthGroup:AddLabel(\"🔴 Low HP Color (Critical):\")\n    HealthGroup:AddColorPicker(\"HealthLowColor\", {Default = Color3.new(1,0,0), Callback = function(v) esplib.healthbar.low_color = v end})\n    \n    HealthGroup:AddLabel(\"🟢 High HP Color (Healthy):\")\n    HealthGroup:AddColorPicker(\"HealthHighColor\", {Default = Color3.new(0,1,0), Callback = function(v) esplib.healthbar.high_color = v end})\n    \n    -- ============ TRACER LINES ============\n    local TracerGroup = Tabs.ESP:AddRightGroupbox(\"📍 Tracer Lines\")\n    TracerGroup:AddLabel(\"Tracer Settings:\")\n    TracerGroup:AddToggle(\"TracerEnabled\", {Text = \"✅ Show Tracers\", Default = true, Callback = function(v) esplib.tracer.enabled = v end})\n    TracerGroup:AddDropdown(\"TracerFrom\", {Text = \"Origin Point\", Values = {\"bottom\", \"center\", \"top\", \"mouse\", \"head\"}, Default = 1, Callback = function(v) esplib.tracer.from = v end})\n    \n    TracerGroup:AddDivider()\n    TracerGroup:AddLabel(\"⚪ Tracer Color:\")\n    TracerGroup:AddColorPicker(\"TracerColor\", {Default = Color3.new(1,1,1), Callback = function(v) esplib.tracer.fill = v end})\n    \n    TracerGroup:AddLabel(\"⬛ Tracer Outline:\")\n    TracerGroup:AddColorPicker(\"TracerOutlineColor\", {Default = Color3.new(0,0,0), Callback = function(v) esplib.tracer.outline = v end})\n    \n    -- ============ DISTANCE FADE ============\n    local FadeGroup = Tabs.ESP:AddRightGroupbox(\"🌫️ Distance Fade\")\n    FadeGroup:AddLabel(\"Fade Settings:\")\n    FadeGroup:AddToggle(\"FadeEnabled\", {Text = \"✅ Enable Fade\", Default = true, Callback = function(v) esplib.fade.enabled = v end})\n    FadeGroup:AddSlider(\"FadeDistance\", {Text = \"Max Detail Distance\", Default = 400, Min = 100, Max = 1000, Rounding = 0, Suffix = \"m\", Compact = true, Callback = function(v) esplib.fade.max_distance = v end})\n    FadeGroup:AddSlider(\"MinTransparency\", {Text = \"Minimum Alpha\", Default = 0.3, Min = 0.0, Max = 1.0, Rounding = 2, Compact = true, Callback = function(v) esplib.fade.min_transparency = v end})\n    \n    FadeGroup:AddDivider()\n    FadeGroup:AddLabel(\"Mouse Highlight:\")\n    FadeGroup:AddToggle(\"HoverEnabled\", {Text = \"✅ Highlight Near Mouse\", Default = true, Callback = function(v) esplib.fade.hover_enabled = v end})\n    FadeGroup:AddSlider(\"HoverRadius\", {Text = \"Highlight Radius\", Default = 200, Min = 50, Max = 500, Rounding = 0, Suffix = \"px\", Compact = true, Callback = function(v) esplib.fade.hover_radius = v end})\n    FadeGroup:AddSlider(\"FadeAnimSpeed\", {Text = \"Animation Speed\", Default = 0.25, Min = 0.05, Max = 1.0, Rounding = 2, Compact = true, Callback = function(v) esplib.fade.animation_speed = v end})\nend\n\n-- ============================================================\n-- UI INITIALIZATION - VISUALS TAB\n-- ============================================================\nlocal function InitVisualsUI()\n    -- ============ CAMERA FOV ============\n    local FOVGroup = Tabs.Visuals:AddLeftGroupbox(\"📷 Camera FOV\")\n    FOVGroup:AddLabel(\"Field of View:\")\n    FOVGroup:AddToggle(\"FOVEnabled\", {\n        Text = \"✅ Enable FOV\",\n        Default = false,\n        Tooltip = \"Changes your camera field of view\",\n        Callback = function(v)\n            local value = v and Library.Options.FOVValue.Value or 70\n            TweenService:Create(camera, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {FieldOfView = value}):Play()\n        end\n    })\n    FOVGroup:AddSlider(\"FOVValue\", {\n        Text = \"FOV Amount\",\n        Default = 90,\n        Min = 50, Max = 120, Rounding = 0, Compact = true,\n        Callback = function(v)\n            if Library.Toggles.FOVEnabled.Value then\n                TweenService:Create(camera, TweenInfo.new(0.6, Enum.EasingStyle.Exponential), {FieldOfView = v}):Play()\n            end\n        end\n    })\n    \n    -- ============ GLOW EFFECT ============\n    local GlowGroup = Tabs.Visuals:AddLeftGroupbox(\"✨ Glow Effect\")\n    GlowGroup:AddLabel(\"Glow Settings:\")\n    GlowGroup:AddToggle(\"GlowEnabled\", {Text = \"✅ Enable Glow\", Default = false, Callback = function(v) esplib.glow.enabled = v end})\n    GlowGroup:AddSlider(\"GlowIntensity\", {Text = \"Intensity\", Default = 0.4, Min = 0.1, Max = 1.0, Rounding = 2, Compact = true, Callback = function(v) esplib.glow.intensity = v end})\n    GlowGroup:AddSlider(\"GlowSize\", {Text = \"Size\", Default = 1.5, Min = 0.5, Max = 5.0, Rounding = 1, Compact = true, Callback = function(v) esplib.glow.size = v end})\n    GlowGroup:AddSlider(\"GlowDistance\", {Text = \"Max Distance\", Default = 150, Min = 50, Max = 300, Rounding = 0, Suffix = \"m\", Compact = true, Callback = function(v) esplib.glow.max_distance = v end})\n    \n    GlowGroup:AddDivider()\n    GlowGroup:AddLabel(\"💫 Glow Color:\")\n    GlowGroup:AddColorPicker(\"GlowColor\", {Default = Color3.new(0, 0.8, 1), Callback = function(v) esplib.glow.color = v end})\n    \n    -- ============ ANIMATIONS ============\n    local AnimGroup = Tabs.Visuals:AddRightGroupbox(\"🎬 ESP Animations\")\n    AnimGroup:AddLabel(\"Main Animation:\")\n    AnimGroup:AddToggle(\"AnimationsEnabled\", {Text = \"✅ Enable Animations\", Default = true, Callback = function(v) esplib.animations.enabled = v end})\n    AnimGroup:AddSlider(\"AnimSpeed\", {Text = \"Overall Speed\", Default = 0.2, Min = 0.05, Max = 1.0, Rounding = 2, Compact = true, Callback = function(v) esplib.animations.speed = v end})\n    \n    AnimGroup:AddDivider()\n    AnimGroup:AddLabel(\"Transition Effects:\")\n    AnimGroup:AddToggle(\"SmoothHealth\", {Text = \"💚 Smooth Health Bars\", Default = true, Callback = function(v) esplib.animations.health_smooth = v end})\n    AnimGroup:AddToggle(\"FadeIn\", {Text = \"🌅 Fade In On Join\", Default = true, Callback = function(v) esplib.animations.fade_in = v end})\n    \n    AnimGroup:AddDivider()\n    AnimGroup:AddLabel(\"Rainbow Effect:\")\n    AnimGroup:AddToggle(\"RainbowEnabled\", {Text = \"🌈 Rainbow Outline\", Default = false, Callback = function(v) esplib.animations.rainbow = v end})\n    AnimGroup:AddSlider(\"RainbowSpeed\", {Text = \"Rainbow Speed\", Default = 0.03, Min = 0.01, Max = 0.1, Rounding = 3, Compact = true, Callback = function(v) esplib.animations.rainbow_speed = v end})\n    \n    AnimGroup:AddDivider()\n    AnimGroup:AddLabel(\"Pulse Effect:\")\n    AnimGroup:AddToggle(\"PulseEnabled\", {Text = \"💓 Pulse Opacity\", Default = false, Callback = function(v) esplib.animations.pulse = v end})\n    AnimGroup:AddSlider(\"PulseSpeed\", {Text = \"Pulse Speed\", Default = 0.08, Min = 0.02, Max = 0.2, Rounding = 3, Compact = true, Callback = function(v) esplib.animations.pulse_speed = v end})\nend\n\n-- ============================================================\n-- UI INITIALIZATION - PLAYERS TAB\n-- ============================================================\nlocal function InitPlayersUI()\n    -- ============ FRIENDS SYSTEM ============\n    local FriendsGroup = Tabs.Players:AddLeftGroupbox(\"👫 Friends System\")\n    FriendsGroup:AddLabel(\"Friends Settings:\")\n    FriendsGroup:AddToggle(\"FriendsEnabled\", {Text = \"✅ Enable System\", Default = true, Callback = function(v) esplib.friends.enabled = v end})\n    FriendsGroup:AddToggle(\"ShowTags\", {Text = \"📌 Show Tags\", Default = true, Callback = function(v) esplib.friends.show_tags = v end})\n    \n    FriendsGroup:AddDivider()\n    FriendsGroup:AddLabel(\"🟢 Friend Color:\")\n    FriendsGroup:AddColorPicker(\"FriendColor\", {Default = Color3.new(0,1,0), Callback = function(v) esplib.friends.friend_color = v end})\n    \n    FriendsGroup:AddLabel(\"🔴 Enemy Color:\")\n    FriendsGroup:AddColorPicker(\"EnemyColor\", {Default = Color3.new(1,0,0), Callback = function(v) esplib.friends.enemy_color = v end})\n    \n    FriendsGroup:AddDivider()\n    FriendsGroup:AddLabel(\"Manage Friends:\")\n    FriendsGroup:AddInput(\"AddFriend\", {\n        Default = \"\", Numeric = false, Finished = true,\n        Text = \"➕ Add Friend\", Placeholder = \"Player Name...\",\n        Callback = function(v)\n            if v and v ~= \"\" then\n                local found = false\n                for _, n in ipairs(esplib.friends.friends_list) do if n == v then found = true break end end\n                if not found then\n                    table.insert(esplib.friends.friends_list, v)\n                    Library:Notify(\"✅ Added: \" .. v, 3)\n                else\n                    Library:Notify(\"⚠️ Already in list\", 2)\n                end\n                Library.Options.AddFriend:SetValue(\"\")\n            end\n        end\n    })\n    FriendsGroup:AddButton({Text = \"🗑️ Clear List\", Func = function()\n        esplib.friends.friends_list = {}\n        Library:Notify(\"🗑️ Cleared\", 3)\n    end})\n    \n    -- ============ VISIBILITY CHECK ============\n    local VisGroup = Tabs.Players:AddRightGroupbox(\"👁️ Visibility Check\")\n    VisGroup:AddLabel(\"Line of Sight:\")\n    VisGroup:AddToggle(\"VisibilityEnabled\", {Text = \"✅ Check LOS\", Default = false, Callback = function(v) esplib.visibility.enabled = v end})\n    \n    VisGroup:AddDivider()\n    VisGroup:AddLabel(\"🟢 Visible Color:\")\n    VisGroup:AddColorPicker(\"VisibleColor\", {Default = Color3.new(0,1,0), Callback = function(v) esplib.visibility.visible_color = v end})\n    \n    VisGroup:AddLabel(\"⬛ Hidden Color:\")\n    VisGroup:AddColorPicker(\"HiddenColor\", {Default = Color3.new(1,0,0), Callback = function(v) esplib.visibility.hidden_color = v end})\n    \n    -- ============ WHITELIST ============\n    local WhitelistGroup = Tabs.Players:AddRightGroupbox(\"⭐ Whitelist\")\n    WhitelistGroup:AddLabel(\"Whitelist Control:\")\n    WhitelistGroup:AddToggle(\"WhitelistEnabled\", {Text = \"✅ Enable Whitelist\", Default = false, Callback = function(v) esplib.whitelist.enabled = v end})\n    \n    WhitelistGroup:AddDivider()\n    WhitelistGroup:AddLabel(\"Manage Whitelist:\")\n    WhitelistGroup:AddInput(\"AddWhitelist\", {\n        Default = \"\", Numeric = false, Finished = true,\n        Text = \"➕ Add Player\", Placeholder = \"Player Name...\",\n        Callback = function(v)\n            if v and v ~= \"\" then\n                local found = false\n                for _, n in ipairs(esplib.whitelist.players) do if n == v then found = true break end end\n                if not found then\n                    table.insert(esplib.whitelist.players, v)\n                    Library:Notify(\"✅ Whitelisted: \" .. v, 3)\n                else\n                    Library:Notify(\"⚠️ Already whitelisted\", 2)\n                end\n                Library.Options.AddWhitelist:SetValue(\"\")\n            end\n        end\n    })\n    WhitelistGroup:AddButton({Text = \"🗑️ Clear Whitelist\", Func = function()\n        esplib.whitelist.players = {}\n        Library:Notify(\"🗑️ Cleared\", 3)\n    end})\nend\n\n-- ============================================================\n-- UI INITIALIZATION - UTILITY TAB\n-- ============================================================\nlocal function InitUtilityUI()\n    -- ============ AUTOMATION ============\n    local AutoGroup = Tabs.Utility:AddLeftGroupbox(\"🤖 Auto ESP\")\n    AutoGroup:AddLabel(\"Automatic ESP:\")\n    AutoGroup:AddToggle(\"AutoESP\", {\n        Text = \"✅ Auto ESP Players\",\n        Default = false,\n        Tooltip = \"Automatically adds ESP to all players\",\n        Callback = function(v)\n            State.autoESP = v\n            if v then\n                local count = 0\n                for _, plr in ipairs(Players:GetPlayers()) do\n                    if plr ~= LocalPlayer and plr.Character then\n                        pcall(function()\n                            esplib.add_box(plr.Character)\n                            esplib.add_healthbar(plr.Character)\n                            esplib.add_name(plr.Character)\n                            esplib.add_distance(plr.Character)\n                            esplib.add_tracer(plr.Character)\n                            count += 1\n                        end)\n                    end\n                end\n                Library:Notify(\"✅ Synced: \" .. count .. \" players\", 3)\n            end\n        end\n    })\n    \n    AutoGroup:AddToggle(\"AutoESPDummy\", {\n        Text = \"🎯 Auto ESP Dummies\",\n        Default = false,\n        Tooltip = \"Automatically adds ESP to dummy targets\",\n        Callback = function(v)\n            State.autoDummy = v\n            Library:Notify(v and \"✅ Enabled\" or \"❌ Disabled\", 3)\n        end\n    })\n    \n    AutoGroup:AddDivider()\n    AutoGroup:AddLabel(\"Manual Actions:\")\n    AutoGroup:AddButton({\n        Text = \"🔄 Apply ESP All Now\",\n        Func = function()\n            local count = 0\n            for _, plr in ipairs(Players:GetPlayers()) do\n                if plr ~= LocalPlayer and plr.Character then\n                    pcall(function()\n                        esplib.add_box(plr.Character)\n                        esplib.add_healthbar(plr.Character)\n                        esplib.add_name(plr.Character)\n                        esplib.add_distance(plr.Character)\n                        esplib.add_tracer(plr.Character)\n                        count += 1\n                    end)\n                end\n            end\n            Library:Notify(\"✅ Added to \" .. count .. \" players\", 3)\n        end\n    })\n    \n    AutoGroup:AddButton({\n        Text = \"🎪 ESP Weakest Dummy\",\n        Tooltip = \"Adds ESP to the weakest training dummy\",\n        Func = function()\n            local live = workspace:FindFirstChild(\"Live\")\n            local dummy = live and live:FindFirstChild(\"Weakest Dummy\")\n            if dummy and dummy:FindFirstChildOfClass(\"Humanoid\") then\n                pcall(function()\n                    esplib.add_box(dummy)\n                    esplib.add_healthbar(dummy)\n                    esplib.add_name(dummy)\n                    esplib.add_distance(dummy)\n                    esplib.add_tracer(dummy)\n                end)\n                Library:Notify(\"✅ ESP Added\", 3)\n            else\n                Library:Notify(\"❌ Dummy Not Found\", 3)\n            end\n        end\n    })\n    \n    -- ============ CACHE CONTROL ============\n    local CacheGroup = Tabs.Utility:AddRightGroupbox(\"🧹 Cache Control\")\n    CacheGroup:AddLabel(\"Memory Management:\")\n    CacheGroup:AddButton({\n        Text = \"🧹 Clean Drawings\",\n        Tooltip = \"Removes ESP drawings from memory\",\n        Func = function()\n            if esplib.cleanup then esplib.cleanup() end\n            Library:Notify(\"✅ Cleaned\", 3)\n        end\n    })\n    \n    CacheGroup:AddButton({\n        Text = \"💥 Force Cleanup\",\n        Tooltip = \"Complete reset (use before re-executing)\",\n        Func = function()\n            if esplib.force_cleanup then esplib.force_cleanup() end\n            Library:Notify(\"✅ Force Cleaned\", 3)\n        end\n    })\nend\n\n-- ============================================================\n-- UI INITIALIZATION - SETTINGS TAB\n-- ============================================================\nlocal function InitSettingsUI()\n    local MenuGroup = Tabs.Settings:AddRightGroupbox(\"⚙️ Menu Settings\")\n    MenuGroup:AddLabel(\"Interface:\")\n    MenuGroup:AddToggle(\"KeybindMenuOpen\", {Default = false, Text = \"📋 Show Keybinds\", Callback = function(v) Library.KeybindFrame.Visible = v end})\n    MenuGroup:AddToggle(\"ShowCustomCursor\", {Text = \"🖱️ Custom Cursor\", Default = true, Callback = function(v) Library.ShowCustomCursor = v end})\n    \n    MenuGroup:AddDivider()\n    MenuGroup:AddLabel(\"Menu Control:\")\n    MenuGroup:AddLabel(\"⌨️ Menu Keybind:\"):AddKeyPicker(\"MenuKeybind\", {Default = \"End\", NoUI = true, Text = \"Toggle\"})\n    \n    MenuGroup:AddDivider()\n    MenuGroup:AddButton({\n        Text = \"🚪 Unload Cheat\",\n        Func = function() Library:Unload() end,\n        DoubleClick = true,\n        Tooltip = \"Double-click to unload completely\"\n    })\nend\n\n-- ============================================================\n-- AUTO ESP SYSTEM\n-- ============================================================\nlocal function addESPToChar(char)\n    task.wait(0.2)\n    pcall(function()\n        esplib.add_box(char)\n        esplib.add_healthbar(char)\n        esplib.add_name(char)\n        esplib.add_distance(char)\n        esplib.add_tracer(char)\n    end)\nend\n\nlocal function handlePlayer(plr)\n    if plr == LocalPlayer then return end\n    \n    table.insert(State.Connections, plr.CharacterAdded:Connect(function(char)\n        if State.autoESP then addESPToChar(char) end\n    end))\n    \n    if plr.Character and State.autoESP then\n        addESPToChar(plr.Character)\n    end\nend\n\nfor _, plr in ipairs(Players:GetPlayers()) do\n    handlePlayer(plr)\nend\n\ntable.insert(State.Connections, Players.PlayerAdded:Connect(function(plr)\n    handlePlayer(plr)\nend))\n\npcall(function()\n    table.insert(State.Connections, workspace.Live.ChildAdded:Connect(function(child)\n        if State.autoDummy and child:FindFirstChildOfClass(\"Humanoid\") then\n            task.wait(0.5)\n            addESPToChar(child)\n        end\n    end))\nend)\n\n-- ============================================================\n-- INITIALIZATION\n-- ============================================================\nLibrary.ToggleKeybind = Library.Options.MenuKeybind\nLibrary:SetWatermark(\"Project Radiant | 0.43\", true)\nLibrary:SetWatermarkVisibility(true)\n\nInitCombatUI()\nInitESPUI()\nInitVisualsUI()\nInitPlayersUI()\nInitUtilityUI()\nInitSettingsUI()\n\n-- ============================================================\n-- SAVE & THEME\n-- ============================================================\nThemeManager:SetLibrary(Library)\nSaveManager:SetLibrary(Library)\nSaveManager:IgnoreThemeSettings()\nSaveManager:SetIgnoreIndexes({\"MenuKeybind\", \"AimSilentKey\", \"AimCameraKey\"})\nThemeManager:SetFolder(\"Project-Radiant\")\nSaveManager:SetFolder(\"Project-Radiant/configs\")\nSaveManager:BuildConfigSection(Tabs.Settings)\nThemeManager:ApplyToTab(Tabs.Settings)\nSaveManager:LoadAutoloadConfig()\n\n-- ============================================================\n-- UNLOAD HANDLER\n-- ============================================================\nLibrary:OnUnload(function()\n    pcall(function()\n        for _, conn in ipairs(State.Connections) do\n            if conn and conn.Disconnect then conn:Disconnect() end\n        end\n    end)\n    \n    pcall(function()\n        if esplib and esplib.force_cleanup then esplib.force_cleanup() end\n    end)\n    \n    pcall(function()\n        if AimbotEnvironment and AimbotEnvironment.Exit then\n            AimbotEnvironment:Exit()\n        end\n    end)\n    \n    pcall(function()\n        if Library.Toggles.FOVEnabled and Library.Toggles.FOVEnabled.Value then\n            TweenService:Create(camera, TweenInfo.new(0.4, Enum.EasingStyle.Sine), {FieldOfView = 70}):Play()\n        end\n    end)\n    \n    getgenv().esplib = nil\n    getgenv().current_esplib = nil\n    getgenv().ProjectRadiant = nil\n    \n    Library:Notify(\"👋 Unloaded\", 3)\nend)\n\nLibrary:Notify(\"✅ Project Radiant 0.43 Loaded!\", 5)\n